package com.example.mediqueue.model;
import jakarta.persistence.*;
@Entity @Table(name="opds") public class Opd{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@Column(nullable=false,unique=true,length=100)String name;@ManyToOne @JoinColumn(name="department_id")Department department;@ManyToOne @JoinColumn(name="doctor_id")Doctor doctor;@Column(length=30)String roomNumber;boolean open=true;public Opd(){}public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public Department getDepartment(){return department;}public void setDepartment(Department v){department=v;}public Doctor getDoctor(){return doctor;}public void setDoctor(Doctor v){doctor=v;}public String getRoomNumber(){return roomNumber;}public void setRoomNumber(String v){roomNumber=v;}public boolean isOpen(){return open;}public void setOpen(boolean v){open=v;}}
